    $("li.Notice",block).css({width: winWidth + 'px'});
}

function slidesRules(data, rem){
    $("div.PanelContainer", data).each(function(){
        if(!rem){
            var slider = $(".PanelsRules", $(this)).bxSlider({
                slideSelector: "div.panel",
                pagerCustom: '.UlNavControls',
                speed: 500,
                auto: true,
                autoHover: true,
                pause: 5000,
                controls: false,
            });
        }else{
            slider.reloadSlider();
        }
    });
}

